const machineInUse = `-- name: MachineInUse :one
SELECT (
    EXISTS (SELECT 1 FROM machine_jobs j WHERE j.machine_id = $1)
    OR EXISTS (SELECT 1 FROM machine_runs mr WHERE mr.machine_id = $1)
    OR EXISTS (SELECT 1 FROM printer_connector_assignments ca WHERE ca.machine_id = $1)
    OR EXISTS (SELECT 1 FROM printer_events pe WHERE pe.machine_id = $1)
    OR EXISTS (SELECT 1 FROM printer_error_occurrences eo WHERE eo.machine_id = $1)
    OR EXISTS (SELECT 1 FROM streaming_cameras sc WHERE sc.machine_id = $1)
    OR EXISTS (
        SELECT 1 FROM printer_spool_assignments a
        JOIN printer_slots s ON s.id = a.slot_id
        JOIN printer_input_units u ON u.id = s.input_unit_id
        WHERE u.machine_id = $1
    )
)::boolean AS in_use
`

// Machines with history, connector assignments, cameras or mounted spools are retired instead of deleted.
func (q *Queries) MachineInUse(ctx context.Context, id uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, machineInUse, id)
	var in_use bool
	err := row.Scan(&in_use)
	return in_use, err
}

const roleInUse = `-- name: RoleInUse :one
SELECT (
    EXISTS (SELECT 1 FROM person_roles pr WHERE pr.role_id = $1)
    OR EXISTS (SELECT 1 FROM visitor_enrollment_configuration vc WHERE vc.initial_role_id = $1)
    OR EXISTS (SELECT 1 FROM event_shift_requirement_roles er WHERE er.role_id = $1)
    OR EXISTS (SELECT 1 FROM open_day_staff_requirement_roles orr WHERE orr.role_id = $1)
)::boolean AS in_use
`

// A role in use is kept by an overwrite: deleting it would silently take it away from people or requirements.
func (q *Queries) RoleInUse(ctx context.Context, id uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, roleInUse, id)
	var in_use bool
	err := row.Scan(&in_use)
	return in_use, err
}
